import"./chunk-VC46IEJQ.js";var e=(o,a)=>({en:o,zh:a}),t=(o,a,n,s,i,h,l,u,r)=>({name:o,desc:a,tour:n,...r?{spoiler:r}:{},source:{confidence:s,refs:i,book:h,unknown:l,interpretation:u}}),d={id:"gulltown",intro:e("Gulltown is the chief port of the Vale, a walled town on a natural harbour of the Narrow Sea, held by House Grafton for the Arryns. The novels mention it often but describe it hardly at all, so nearly everything you see here is reconstruction.","\u6D77\u9E25\u9547\u662F\u8C37\u5730\u7684\u9996\u8981\u6E2F\u53E3\uFF0C\u4E00\u5EA7\u6FD2\u4E34\u72ED\u6D77\u5929\u7136\u826F\u6E2F\u7684\u8BBE\u9632\u57CE\u9547\uFF0C\u7531\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u66FF\u827E\u6797\u5BB6\u9547\u5B88\u3002\u5C0F\u8BF4\u5C61\u6B21\u63D0\u53CA\u6B64\u5730\uFF0C\u5374\u51E0\u4E4E\u4ECE\u672A\u63CF\u5199\u5176\u6837\u8C8C\uFF0C\u56E0\u6B64\u773C\u524D\u6240\u89C1\u5927\u591A\u51FA\u81EA\u91CD\u6784\u3002"),notes:e("Established: Gulltown is the Vale's main seaport, walled, on a natural harbour, ruled by House Grafton as Arryn bannermen; reference sources add the Motherhouse of Maris on an island in the harbour. Invented: the sand-and-slate palette, terraced streets, moles, market, keep and lighthouse. No lighthouse is attested at all; it is pure interpretation.","\u6709\u636E\u53EF\u67E5\uFF1A\u6D77\u9E25\u9547\u662F\u8C37\u5730\u7684\u4E3B\u8981\u6D77\u6E2F\uFF0C\u6709\u57CE\u5899\uFF0C\u5750\u62E5\u5929\u7136\u6E2F\u6E7E\uFF0C\u7531\u827E\u6797\u5BB6\u7684\u5C01\u81E3\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u7EDF\u6CBB\uFF1B\u53C2\u8003\u8D44\u6599\u53E6\u8F7D\u6E2F\u4E2D\u5C0F\u5C9B\u4E0A\u6709\u9A6C\u91CC\u65AF\u6BCD\u9662\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6C99\u8272\u4E0E\u677F\u5CA9\u8272\u7684\u914D\u8272\u3001\u9636\u68AF\u8857\u5DF7\u3001\u9632\u6CE2\u5824\u3001\u5E02\u96C6\u3001\u57CE\u5821\u4E0E\u706F\u5854\u3002\u706F\u5854\u5168\u65E0\u51FA\u5904\uFF0C\u7EAF\u5C5E\u6F14\u7ECE\u3002"),tour:["harbour","lighthouse","sea-wall","docks","market-square","motherhouse-of-maris","gull-tower","grafton-keep","city-walls"],sources:[{ref:"affc",checked:"memory",note:e("Gulltown and its lord Grafton figure in Alayne's chapters as part of Littlefinger's dealings in the Vale; the town itself is barely described. Recalled, not re-read.","\u6D77\u9E25\u9547\u53CA\u5176\u9886\u4E3B\u845B\u62C9\u592B\u987F\u51FA\u73B0\u5728\u73CA\u838E\u9690\u59D3\u57CB\u540D\u671F\u95F4\u7684\u7AE0\u8282\u4E2D\uFF0C\u7275\u6D89\u5C0F\u6307\u5934\u5728\u8C37\u5730\u7684\u5E03\u5C40\uFF1B\u57CE\u9547\u672C\u8EAB\u51E0\u65E0\u63CF\u5199\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002")},{ref:"twoiaf",checked:"memory",note:e("Gulltown's role as the Vale's trading port and its long history under the Graftons and the Arryns of Gulltown. Recalled; details may be imprecise.","\u6D77\u9E25\u9547\u4F5C\u4E3A\u8C37\u5730\u8D38\u6613\u6E2F\u7684\u5730\u4F4D\uFF0C\u4EE5\u53CA\u5B83\u5728\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u548C\u6D77\u9E25\u9547\u827E\u6797\u5BB6\u6CBB\u4E0B\u7684\u60A0\u4E45\u5386\u53F2\u3002\u51ED\u8BB0\u5FC6\uFF0C\u7EC6\u8282\u6216\u6709\u51FA\u5165\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("A search summary of the wiki confirmed the natural harbour, the town walls, the Motherhouse of Maris on a stony island in the harbour and a semi-canon Gull Tower. It found no lighthouse. Pages not fetched.","\u7EF4\u57FA\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u5929\u7136\u6E2F\u6E7E\u3001\u57CE\u5899\u3001\u6E2F\u4E2D\u77F3\u5C9B\u4E0A\u7684\u9A6C\u91CC\u65AF\u6BCD\u9662\uFF0C\u4EE5\u53CA\u4E00\u5EA7\u51FA\u81EA\u534A\u5B98\u65B9\u8D44\u6599\u7684\u6D77\u9E25\u5854\uFF1B\u672A\u89C1\u4EFB\u4F55\u706F\u5854\u3002\u9875\u9762\u672A\u6293\u53D6\u3002")}],landmarks:{harbour:t(e("The Harbour","\u6D77\u6E2F"),e("A deep natural harbour with quays and piers, where ships bound to and from King's Landing, Braavos and the north put in.","\u5929\u7136\u6DF1\u6C34\u826F\u6E2F\uFF0C\u7801\u5934\u6808\u6865\u6797\u7ACB\uFF0C\u5F80\u6765\u541B\u4E34\u3001\u5E03\u62C9\u4F5B\u65AF\u4E0E\u5317\u65B9\u7684\u8239\u53EA\u5728\u6B64\u505C\u9760\u3002"),e("A natural harbour, the Vale's main window on the Narrow Sea.","\u5929\u7136\u826F\u6E2F\uFF0C\u662F\u8C37\u5730\u9762\u5411\u72ED\u6D77\u7684\u4E3B\u8981\u95E8\u6237\u3002"),"medium",["affc","twoiaf","awoiaf"],e("Gulltown is the Vale's chief port on a natural harbour.","\u6D77\u9E25\u9547\u662F\u8C37\u5730\u7684\u9996\u8981\u6E2F\u53E3\uFF0C\u5750\u62E5\u5929\u7136\u6E2F\u6E7E\u3002"),e("Its depth, extent, number of berths and the routes that actually use it.","\u6C34\u6DF1\u3001\u8303\u56F4\u3001\u6CCA\u4F4D\u6570\uFF0C\u4EE5\u53CA\u5B9E\u9645\u53D6\u9053\u6B64\u6E2F\u7684\u822A\u7EBF\u3002"),e("A round basin with piers and moored ships; the trade routes named in the description are plausible, not cited.","\u5706\u5F62\u6E2F\u6C60\uFF0C\u914D\u6808\u6865\u4E0E\u6CCA\u8239\uFF1B\u6587\u4E2D\u6240\u4E3E\u822A\u7EBF\u5408\u4E4E\u60C5\u7406\uFF0C\u4F46\u65E0\u5177\u4F53\u51FA\u5904\u3002")),lighthouse:t(e("Lighthouse","\u706F\u5854"),e("A tall white tower at the end of the east mole, its lantern room lit to guide ships into the harbour mouth.","\u4E1C\u5824\u5C3D\u5934\u4E00\u5EA7\u767D\u8272\u9AD8\u5854\uFF0C\u706F\u5BA4\u4EAE\u7740\u706B\u5149\uFF0C\u4E3A\u5165\u6E2F\u8239\u53EA\u5F15\u8DEF\u3002"),e("No source gives Gulltown a lighthouse; this one is our invention.","\u6CA1\u6709\u4EFB\u4F55\u8D44\u6599\u63D0\u5230\u6D77\u9E25\u9547\u6709\u706F\u5854\uFF0C\u8FD9\u5EA7\u5854\u662F\u672C\u573A\u666F\u7684\u865A\u6784\u3002"),"low",["awoiaf"],e("Nothing. No lighthouse at Gulltown is attested; the famous Westerosi beacon tower is Oldtown's Hightower.","\u65E0\u3002\u6D77\u9E25\u9547\u5E76\u65E0\u706F\u5854\u7684\u8BB0\u8F7D\uFF1B\u7EF4\u65AF\u7279\u6D1B\u8457\u540D\u7684\u706F\u5854\u662F\u65E7\u9547\u7684\u9AD8\u5854\u3002"),e("Whether any lighthouse or beacon exists.","\u662F\u5426\u5B58\u5728\u4EFB\u4F55\u706F\u5854\u6216\u70FD\u706B\u3002"),e("Added only to give the port a silhouette distinct from Lannisport and White Harbor.","\u4EC5\u4E3A\u4F7F\u6B64\u6E2F\u7684\u8F6E\u5ED3\u6709\u522B\u4E8E\u5170\u5C3C\u65AF\u6E2F\u4E0E\u767D\u6E2F\u800C\u6DFB\u52A0\u3002")),"sea-wall":t(e("Sea-Wall","\u6D77\u5824"),e("Two stone moles curve out to sea to shelter the harbour, leaving a narrow mouth between them.","\u4E24\u9053\u77F3\u5824\u5F2F\u5165\u6D77\u4E2D\uFF0C\u73AF\u62A4\u6E2F\u6E7E\uFF0C\u4E2D\u95F4\u53EA\u7559\u4E00\u9053\u7A84\u53E3\u3002"),e("Two arms of stone shelter the harbour; ships enter between them.","\u4E24\u9053\u77F3\u5824\u73AF\u62B1\u6E2F\u6E7E\uFF0C\u8239\u53EA\u4ECE\u4E2D\u95F4\u9A76\u5165\u3002"),"low",["awoiaf"],e("No breakwater is described in any source we know.","\u5C31\u6211\u4EEC\u6240\u77E5\uFF0C\u4EFB\u4F55\u8D44\u6599\u90FD\u672A\u63CF\u5199\u9632\u6CE2\u5824\u3002"),e("Whether Gulltown has moles at all.","\u6D77\u9E25\u9547\u662F\u5426\u771F\u6709\u9632\u6CE2\u5824\u3002"),e("Moles invented to enclose the harbour.","\u4E3A\u56F4\u5408\u6E2F\u6E7E\u800C\u865A\u6784\u7684\u77F3\u5824\u3002")),docks:t(e("Docks and Warehouses","\u7801\u5934\u4E0E\u8D27\u6808"),e("Stone quays and long, low warehouses where cargo from across the Narrow Sea is landed, counted and taxed.","\u77F3\u780C\u7801\u5934\u4E0E\u4F4E\u77EE\u7684\u957F\u6761\u8D27\u6808\uFF0C\u72ED\u6D77\u5BF9\u5CB8\u7684\u8D27\u7269\u5728\u6B64\u5378\u8239\u3001\u6E05\u70B9\u3001\u7EB3\u7A0E\u3002"),e("Cargo comes ashore here before travelling inland to the Vale.","\u8D27\u7269\u5728\u6B64\u4E0A\u5CB8\uFF0C\u518D\u8F6C\u8FD0\u8C37\u5730\u8179\u5730\u3002"),"medium",["twoiaf"],e("Gulltown is the Vale's trading gateway.","\u6D77\u9E25\u9547\u662F\u8C37\u5730\u7684\u8D38\u6613\u95E8\u6237\u3002"),e("The layout of the quays and any customs house.","\u7801\u5934\u5E03\u5C40\uFF0C\u4EE5\u53CA\u6709\u65E0\u7A0E\u5173\u3002"),e("The ring of quays, piers and warehouses is invented.","\u73AF\u5F62\u7801\u5934\u3001\u6808\u6865\u4E0E\u8D27\u6808\u5747\u4E3A\u865A\u6784\u3002")),"market-square":t(e("Market Square","\u5E02\u96C6\u5E7F\u573A"),e("A cobbled square under striped awnings where fish, cloth and foreign goods are sold.","\u94FA\u77F3\u5E7F\u573A\u4E0A\u652F\u7740\u6761\u7EB9\u906E\u7BF7\uFF0C\u552E\u5356\u9C7C\u8D27\u3001\u5E03\u5339\u4E0E\u8236\u6765\u54C1\u3002"),e("Fish, cloth and foreign spice change hands under striped awnings.","\u6761\u7EB9\u906E\u7BF7\u4E0B\uFF0C\u9C7C\u8D27\u3001\u5E03\u5339\u4E0E\u5F02\u56FD\u9999\u6599\u5728\u6B64\u4EA4\u6613\u3002"),"low",["twoiaf"],e("A busy port implies markets, but none is described.","\u7E41\u5FD9\u7684\u6E2F\u53E3\u81EA\u7136\u6709\u5E02\u96C6\uFF0C\u4F46\u4E66\u4E2D\u672A\u4F5C\u63CF\u5199\u3002"),e("Position and form.","\u4F4D\u7F6E\u4E0E\u5F62\u5236\u3002"),e("A single central square near the harbour is invented.","\u6E2F\u8FB9\u4E00\u5EA7\u4E2D\u5FC3\u5E7F\u573A\u4E3A\u865A\u6784\u3002")),"motherhouse-of-maris":t(e("Motherhouse of Maris","\u9A6C\u91CC\u65AF\u6BCD\u9662"),e("A walled religious house on a stony island in the harbour.","\u6E2F\u4E2D\u77F3\u5C9B\u4E0A\u4E00\u5EA7\u56F4\u5899\u73AF\u7ED5\u7684\u5B97\u6559\u9662\u6240\u3002"),e("A walled religious house on a rocky island, set apart from the town.","\u7901\u5C9B\u4E0A\u7684\u4FEE\u9662\u56F4\u5899\u9AD8\u7B51\uFF0C\u4E0E\u57CE\u9547\u9694\u6C34\u76F8\u671B\u3002"),"low",["awoiaf"],e("Reference sources place the Motherhouse of Maris on a stony island in Gulltown's harbour.","\u53C2\u8003\u8D44\u6599\u79F0\u9A6C\u91CC\u65AF\u6BCD\u9662\u4F4D\u4E8E\u6D77\u9E25\u9547\u6E2F\u4E2D\u7684\u4E00\u5EA7\u77F3\u5C9B\u4E0A\u3002"),e("Its order, purpose and architecture.","\u6240\u5C5E\u6559\u56E2\u3001\u804C\u80FD\u4E0E\u5EFA\u7B51\u5F62\u5236\u3002"),e("The low hall, small tower and ring wall are invented.","\u4F4E\u77EE\u5385\u5802\u3001\u5C0F\u5854\u4E0E\u73AF\u5899\u5747\u4E3A\u865A\u6784\u3002")),"gull-tower":t(e("Gull Tower","\u6D77\u9E25\u5854"),e("A slender white tower on the hill above the market, the highest point in town.","\u5E02\u96C6\u4E0A\u65B9\u5C71\u5761\u4E0A\u7684\u4E00\u5EA7\u7EA4\u7EC6\u767D\u5854\uFF0C\u662F\u5168\u9547\u7684\u5236\u9AD8\u70B9\u3002"),e("A slender tower on the hill; its name comes from a semi-canon source.","\u5C71\u5761\u4E0A\u7684\u4E00\u5EA7\u7EC6\u5854\uFF0C\u540D\u79F0\u51FA\u81EA\u534A\u5B98\u65B9\u8D44\u6599\u3002"),"low",["awoiaf"],e("A wiki entry lists a Gull Tower, citing semi-canon material rather than the novels.","\u7EF4\u57FA\u6536\u6709\u6D77\u9E25\u5854\u4E00\u6761\uFF0C\u51FA\u5904\u662F\u534A\u5B98\u65B9\u8D44\u6599\u800C\u975E\u5C0F\u8BF4\u3002"),e("Whether it is canon, and what kind of building it is.","\u662F\u5426\u5C5E\u4E8E\u6B63\u5178\uFF0C\u4EE5\u53CA\u7A76\u7ADF\u662F\u4F55\u79CD\u5EFA\u7B51\u3002"),e("Placed on the hill and treated as a watchtower.","\u7F6E\u4E8E\u5C71\u5761\uFF0C\u6309\u77AD\u671B\u5854\u5904\u7406\u3002")),"grafton-keep":t(e("Grafton Keep","\u845B\u62C9\u592B\u987F\u5821"),e("The lord's keep on the highest ground, a squat fortress inside its own wall above the town.","\u9886\u4E3B\u57CE\u5821\u96C4\u8E1E\u6700\u9AD8\u5904\uFF0C\u77EE\u58EE\u575A\u56FA\uFF0C\u81EA\u6709\u56F4\u5899\uFF0C\u4FEF\u77B0\u5168\u9547\u3002"),e("House Grafton rules Gulltown for the Arryns; their seat here is our guess.","\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u66FF\u827E\u6797\u5BB6\u7EDF\u6CBB\u6D77\u9E25\u9547\uFF1B\u57CE\u5821\u7684\u6837\u8C8C\u51FA\u81EA\u6211\u4EEC\u7684\u63A8\u60F3\u3002"),"low",["affc","twoiaf"],e("House Grafton rules Gulltown; the form and site of its seat are not described.","\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u7EDF\u6CBB\u6D77\u9E25\u9547\uFF1B\u5176\u5C45\u57CE\u7684\u5F62\u5236\u4E0E\u4F4D\u7F6E\u5747\u65E0\u63CF\u5199\u3002"),e("Everything about the keep.","\u5173\u4E8E\u8FD9\u5EA7\u57CE\u5821\u7684\u4E00\u5207\u3002"),e("A square keep with four turrets, invented.","\u56DB\u89D2\u5E26\u5854\u697C\u7684\u65B9\u5F62\u4E3B\u5821\uFF0C\u7CFB\u865A\u6784\u3002")),"city-walls":t(e("Town Walls","\u57CE\u5899"),e("A towered landward wall with gates, running from shore to shore behind the hill.","\u9646\u4FA7\u57CE\u5899\u8BBE\u6709\u5854\u697C\u4E0E\u57CE\u95E8\uFF0C\u7ED5\u8FC7\u5C71\u540E\uFF0C\u4E24\u7AEF\u62B5\u6D77\u3002"),e("Walls guard the landward side; the sea is the town's other gate.","\u57CE\u5899\u5B88\u62A4\u9646\u4FA7\uFF0C\u5927\u6D77\u5219\u662F\u5C0F\u9547\u7684\u53E6\u4E00\u9053\u95E8\u3002"),"medium",["awoiaf","twoiaf"],e("Gulltown is a walled town.","\u6D77\u9E25\u9547\u6709\u57CE\u5899\u3002"),e("Height, circuit and number of gates.","\u57CE\u5899\u9AD8\u5EA6\u3001\u5468\u957F\u4E0E\u57CE\u95E8\u6570\u91CF\u3002"),e("A single arc with eight towers and a main gate to the north.","\u5355\u9053\u5F27\u5F62\u57CE\u5899\uFF0C\u516B\u5EA7\u5854\u697C\uFF0C\u5317\u9762\u8BBE\u4E3B\u95E8\u3002"))}};export{d as default};
